const TOKEN = "xtk2IC-TUZC034x4yucY-W2t43DutsqWCvwX61fFZLk";
const AUTH = "Basic " + btoa(`0:${TOKEN}`);

async function api(method: string, path: string, body?: any) {
  const url = `${BASE}${path}`;
  const opts: any = {
    method,
    headers: { "Authorization": AUTH, "Content-Type": "application/json" },
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  const text = await res.text();
  let json: any;
  try { json = JSON.parse(text); } catch { json = text; }
  if (!res.ok) {
    console.error(`${method} ${path} => ${res.status}`, JSON.stringify(json).slice(0, 500));
    throw new Error(`${res.status}`);
  }
  if (json.values !== undefined) return json.values;
  if (json.value !== undefined) return json.value;
  return json;
}

// Fetch all vouchers for Jan-Feb 2026
const vouchers = await api("GET", "/ledger/voucher?dateFrom=2026-01-01&dateTo=2026-03-01&fields=*&count=1000");
console.log(`Found ${vouchers.length} vouchers`);

// Print each voucher with its postings
for (const v of vouchers) {
  const postings = v.postings || [];
  const postingsSummary = postings.map((p: any) => {
    const acctNum = p.account?.number;
    const acctName = p.account?.name;
    const acctId = p.account?.id;
